/**
 * Handles the {@code lombok.FieldDefaults} annotation for javac.
 */
@Provides(JavacASTVisitor.class)
@HandlerPriority(-2048) //-2^11; to ensure @Value picks up on messing with the fields' 'final' state, run earlier.
public class HandleFieldDefaults extends JavacASTAdapter {
public boolean generateFieldDefaultsForType(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean makeFinal, boolean checkForTypeLevelFieldDefaults) {
		this.fieldDefaultType = typeNode;
		this.fieldDefaultError = errorNode;
		this.fieldDefaultAccess = level;
		this.fieldDefaultMakeFinal = makeFinal;


		rememberFieldDefaultState(typeNode, errorNode, level, makeFinal);
		return applyFieldDefaultsUsingRememberedState(checkForTypeLevelFieldDefaults);
	}

public void setFieldDefaultsForField(JavacNode fieldNode, AccessLevel level, boolean makeFinal) {
		this.fieldDefaultAccess = level;
		this.fieldDefaultMakeFinal = makeFinal;


		JCVariableDecl field = (JCVariableDecl) fieldNode.get();
		if (level != null && level != AccessLevel.NONE) {
			if ((field.mods.flags & (Flags.PUBLIC | Flags.PRIVATE | Flags.PROTECTED)) == 0) {
				if (!hasAnnotationAndDeleteIfNeccessary(PackagePrivate.class, fieldNode)) {
					if ((field.mods.flags & Flags.STATIC) == 0) {
						field.mods.flags |= toJavacModifier(level);
					}
				}
			}
		}

		if (makeFinal && (field.mods.flags & Flags.FINAL) == 0) {
			if (!hasAnnotationAndDeleteIfNeccessary(NonFinal.class, fieldNode)) {
				if ((field.mods.flags & Flags.STATIC) == 0) {
					field.mods.flags |= Flags.FINAL;
				}
			}
		}

		fieldNode.rebuild();
	}

@Override public void visitType(JavacNode typeNode, JCClassDecl type) {
		this.fieldDefaultType = typeNode;


		AnnotationValues<FieldDefaults> fieldDefaults = null;
		JavacNode source = typeNode;

		boolean levelIsExplicit = false;
		boolean makeFinalIsExplicit = false;
		FieldDefaults fd = null;
		for (JavacNode jn : typeNode.down()) {
			if (jn.getKind() != Kind.ANNOTATION) continue;
			JCAnnotation ann = (JCAnnotation) jn.get();
			JCTree typeTree = ann.annotationType;
			if (typeTree == null) continue;
			String typeTreeToString = typeTree.toString();
			if (!typeTreeToString.equals("FieldDefaults") && !typeTreeToString.equals("lombok.experimental.FieldDefaults")) continue;
			if (!typeMatches(FieldDefaults.class, jn, typeTree)) continue;

			source = jn;
			fieldDefaults = createAnnotation(FieldDefaults.class, jn);
			levelIsExplicit = fieldDefaults.isExplicit("level");
			makeFinalIsExplicit = fieldDefaults.isExplicit("makeFinal");

			handleExperimentalFlagUsage(jn, ConfigurationKeys.FIELD_DEFAULTS_FLAG_USAGE, "@FieldDefaults");

			fd = fieldDefaults.getInstance();
			if (!levelIsExplicit && !makeFinalIsExplicit) {
				jn.addError("This does nothing; provide either level or makeFinal or both.");
			}

			if (levelIsExplicit && fd.level() == AccessLevel.NONE) {
				jn.addError("AccessLevel.NONE doesn't mean anything here. Pick another value.");
				levelIsExplicit = false;
			}

			deleteAnnotationIfNeccessary(jn, FieldDefaults.class);
			deleteImportFromCompilationUnit(jn, "lombok.AccessLevel");
			break;
		}

		if (fd == null && (type.mods.flags & (Flags.INTERFACE | Flags.ANNOTATION)) != 0) return;

		boolean defaultToPrivate = levelIsExplicit ? false : Boolean.TRUE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.FIELD_DEFAULTS_PRIVATE_EVERYWHERE));
		boolean defaultToFinal = makeFinalIsExplicit ? false : Boolean.TRUE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.FIELD_DEFAULTS_FINAL_EVERYWHERE));

		if (!defaultToPrivate && !defaultToFinal && fieldDefaults == null) return;
		AccessLevel fdAccessLevel = (fieldDefaults != null && levelIsExplicit) ? fd.level() : defaultToPrivate ? AccessLevel.PRIVATE : null;
		boolean fdToFinal = (fieldDefaults != null && makeFinalIsExplicit) ? fd.makeFinal() : defaultToFinal;

		generateFieldDefaultsForType(typeNode, source, fdAccessLevel, fdToFinal, false);
	}


	private AccessLevel fieldDefaultAccess;
	private boolean fieldDefaultMakeFinal;
	private JavacNode fieldDefaultType;
	private JavacNode fieldDefaultError;

	private JavacNode getterTypeNode;
	private JavacNode getterErrorNode;
	private AccessLevel getterLevel;
	private boolean getterCheckForTypeLevel;
	private List<JCAnnotation> getterOnMethod;
	private boolean getterLazy;

	private JavacNode setterTypeNode;
	private JavacNode setterErrorNode;
	private AccessLevel setterLevel;
	private boolean setterCheckForTypeLevel;
	private List<JCAnnotation> setterOnMethod;
	private List<JCAnnotation> setterOnParam;

	private JavacNode constructorTypeNode;
	private JavacNode constructorSourceNode;
	private AccessLevel constructorLevel;
	private String constructorStaticName;
	private HandleConstructor.SkipIfConstructorExists constructorSkipMode;

	private JavacNode toStringTypeNode;
	private JavacNode toStringErrorNode;
	private boolean toStringIncludeFieldNames;
	private FieldAccess toStringFieldAccess;

	private JavacNode valueTypeNode;
	private JavacNode valueAnnotationNode;
	private String valueStaticConstructorName;

	private JavacNode dataTypeNode;
	private JavacNode dataAnnotationNode;
	private String dataStaticConstructorName;

	private void rememberFieldDefaultState(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean makeFinal) {
		this.fieldDefaultType = typeNode;
		this.fieldDefaultError = errorNode;
		this.fieldDefaultAccess = level;
		this.fieldDefaultMakeFinal = makeFinal;
	}

	private boolean fieldDefaultTypeIsUsable() {

		return fieldDefaultType != null && fieldDefaultError != null;
	}

	private void applyRememberedFieldDefaultsToEachField() {

		if (!fieldDefaultTypeIsUsable()) return;
		for (JavacNode field : fieldDefaultType.down()) {
			if (field.getKind() != Kind.FIELD) continue;
			JCVariableDecl fieldDecl = (JCVariableDecl) field.get();
			if (fieldDecl.name.toString().startsWith("$")) continue;
			setFieldDefaultsForField(field, fieldDefaultAccess, fieldDefaultMakeFinal);
		}
	}

	public boolean applyFieldDefaultsUsingRememberedState(boolean checkForTypeLevelFieldDefaults) {

		if (!fieldDefaultTypeIsUsable()) return false;
		if (checkForTypeLevelFieldDefaults && hasAnnotation(FieldDefaults.class, fieldDefaultType)) return true;
		if (!isClassOrEnum(fieldDefaultType)) {
			fieldDefaultError.addError("@FieldDefaults is only supported on a class or an enum.");
			return false;
		}
		applyRememberedFieldDefaultsToEachField();
		return true;
	}

	private void rememberGetterState(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean checkForTypeLevelGetter, List<JCAnnotation> onMethod) {
		this.getterTypeNode = typeNode;
		this.getterErrorNode = errorNode;
		this.getterLevel = level;
		this.getterCheckForTypeLevel = checkForTypeLevelGetter;
		this.getterOnMethod = onMethod;
		this.getterLazy = false;
	}

	private boolean getterStateIsReady() {

		return getterTypeNode != null && getterErrorNode != null;
	}

	private void generateRememberedGetters() {

		if (!getterStateIsReady()) return;
		if (getterCheckForTypeLevel && hasAnnotation(Getter.class, getterTypeNode)) return;
		if (!isClassOrEnum(getterTypeNode)) {
			getterErrorNode.addError(GETTER_NODE_NOT_SUPPORTED_ERR);
			return;
		}
		for (JavacNode field : getterTypeNode.down()) {
			if (fieldQualifiesForGetterGeneration(field)) {
				generateGetterForField(field, getterErrorNode.get(), getterLevel, getterLazy, getterOnMethod);
			}
		}
	}

	public void applyGetterGeneration(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean checkForTypeLevelGetter, List<JCAnnotation> onMethod) {
		this.getterTypeNode = typeNode;
		this.getterErrorNode = errorNode;
		this.getterLevel = level;
		this.getterOnMethod = onMethod;
		this.getterCheckForTypeLevel = checkForTypeLevelGetter;


		rememberGetterState(typeNode, errorNode, level, checkForTypeLevelGetter, onMethod);
		if (getterStateIsReady()) generateRememberedGetters();
	}

	private void rememberSetterState(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean checkForTypeLevelSetter, List<JCAnnotation> onMethod, List<JCAnnotation> onParam) {
		this.setterTypeNode = typeNode;
		this.setterErrorNode = errorNode;
		this.setterLevel = level;
		this.setterCheckForTypeLevel = checkForTypeLevelSetter;
		this.setterOnMethod = onMethod;
		this.setterOnParam = onParam;
	}

	private boolean setterStateIsReady() {

		return setterTypeNode != null && setterErrorNode != null;
	}

	private void generateRememberedSetters() {

		if (!setterStateIsReady()) return;
		generateSetterForType(setterTypeNode, setterErrorNode, setterLevel, setterCheckForTypeLevel, setterOnMethod, setterOnParam);
	}

	public void applySetterGeneration(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean checkForTypeLevelSetter, List<JCAnnotation> onMethod, List<JCAnnotation> onParam) {
		this.setterTypeNode = typeNode;
		this.setterErrorNode = errorNode;
		this.setterLevel = level;
		this.setterOnMethod = onMethod;
		this.setterOnParam = onParam;
		this.setterCheckForTypeLevel = checkForTypeLevelSetter;

